			rs1_x0_val: assert((rvfi_insn[19:15] != 5'd0) || (rvfi_rs1_rdata == 0));
			rs2_x0_val: assert((rvfi_insn[24:20] != 5'd0) || (rvfi_rs2_rdata == 0));

			// Structural lemma: BGE can only jump to PC+4 or PC+imm.
			pc_wdata_oneof: assert((rvfi_pc_wdata == h_bge_pc_plus4) || (rvfi_pc_wdata == h_bge_pc_plusimm));
